-- полное равенство групп, суммы добычи и числа ACTIVE-строк пересчёту из факта.
WITH e AS (SELECT p.production_date,p.field_hk,f.field_name,f.region,CAST(sum(p.oil_tonnes) AS decimal(22,3)) AS oil_tonnes,sum(CASE WHEN p.status='ACTIVE' THEN CAST(1 AS bigint) ELSE CAST(0 AS bigint) END) AS producing_well_days FROM {{target:oil_mart__fact_well_day}} p JOIN {{target:oil_mart__dim_field}} f ON f.field_hk=p.field_hk AND f.entity_version=p.field_version GROUP BY p.production_date,p.field_hk,f.field_name,f.region), t AS (SELECT production_date,field_hk,field_name,region,oil_tonnes,producing_well_days FROM {{target:oil_mart__agg_field_day}}), d AS ((SELECT * FROM e EXCEPT ALL SELECT * FROM t) UNION ALL (SELECT * FROM t EXCEPT ALL SELECT * FROM e)) SELECT count(*) AS n FROM d;
